                    ByteArrayInputStream in = new ByteArrayInputStream(data);
                    while (bytesRead < data.length) {
                        int n = in.read(buffer);
                        bytesRead += n;
                        out.write(buffer, 0, n);
                    }
                } else {
                    out.write(data);
                }
            } catch (IOException e) {
                log.error("Unexpected error while reading HTTP input stream", e);
            }
        }
