        } else if (input.getBody() instanceof byte[]) {
            return new EventEnvelope().setBody(input.getBody())
                    .setHeader("content-type", "application/octet-stream");
        } else {
            // returning AsyncHttpRequest is an edge case
            return body;
        }
    }

