    org.platformlambda.core.serializers.SimpleMapper mapper = org.platformlambda.core.serializers.SimpleMapper.getInstance();
    java.lang.String NUMBER = "number";
    java.lang.String ONE = "0.00000001";
    java.lang.String ZERO = "0.00000000";
    org.platformlambda.core.SimpleMapperTest.SimpleNumber one = new org.platformlambda.core.SimpleMapperTest.SimpleNumber(ONE);
    org.platformlambda.core.SimpleMapperTest.SimpleNumber zero = new org.platformlambda.core.SimpleMapperTest.SimpleNumber(ZERO);
    // verify hash map result
    java.util.Map<java.lang.String, java.lang.Object> mapOne = mapper.getMapper().readValue(one, java.util.Map.class);
    // numeric value is preserved
    org.junit.Assert.assertEquals(ONE, mapOne.get(NUMBER));
    // ensure that ZERO is converted to "0"
    java.util.Map<java.lang.String, java.lang.Object> mapZero = mapper.getMapper().readValue(zero, java.util.Map.class);
    org.junit.Assert.assertEquals("0", mapZero.get(NUMBER));
    // verify PoJo class conversion behavior - this will return the original object because the class is the same
    org.platformlambda.core.SimpleMapperTest.SimpleNumber numberOne = mapper.getMapper().readValue(one, org.platformlambda.core.SimpleMapperTest.SimpleNumber.class);
    org.junit.Assert.assertEquals(numberOne.number, one.number);
    // this will pass thru the serializer
    java.lang.String zeroValue = mapper.getMapper().writeValueAsString(zero);
    org.platformlambda.core.SimpleMapperTest.SimpleNumber numberZero = mapper.getMapper().readValue(zeroValue, org.platformlambda.core.SimpleMapperTest.SimpleNumber.class);
    // the original number has the zero number with many zeros after the decimal
    org.junit.Assert.assertEquals("0E-8", zero.number.toString());
    org.junit.Assert.assertEquals(ZERO, zero.number.toPlainString());
    // the converted BigDecimal gets a zero number without zeros after the decimal
    org.junit.Assert.assertEquals("0", numberZero.number.toString());
    // verify map to PoJo serialization behavior
    org.platformlambda.core.SimpleMapperTest.SimpleNumber number0 = mapper.getMapper().readValue(mapZero, org.platformlambda.core.SimpleMapperTest.SimpleNumber.class);
    org.junit.Assert.assertTrue(mapper.isZero(number0.number));
    org.junit.Assert.assertTrue(mapper.isZero(zero.number));
    // the two zero objects are different because of precision
    org.junit.Assert.assertNotEquals(number0.number, zero.number);
    org.platformlambda.core.SimpleMapperTest.SimpleNumber number1 = mapper.getMapper().readValue(mapOne, org.platformlambda.core.SimpleMapperTest.SimpleNumber.class);
    // non-zero numbers are exactly the same
    org.junit.Assert.assertEquals(number1.number, one.number);
}

