    java.util.Map<java.lang.String, java.lang.Object> flatMap = util.getFlatMap(map);
    org.junit.Assert.assertEquals("data", flatMap.get(org.platformlambda.core.UtilityTests.HELLO_WORLD));
    org.junit.Assert.assertEquals(1, flatMap.get("hello.number[0]"));
    org.junit.Assert.assertEquals(2, flatMap.get("hello.number[1]"));
    org.junit.Assert.assertEquals("data", flatMap.get("hello.number[2].hello.world"));
    org.junit.Assert.assertEquals(1, flatMap.get("hello.number[2].hello.number[0]"));
    org.junit.Assert.assertEquals(2, flatMap.get("hello.number[2].hello.number[1]"));
    /* flatmap's keys are composite keys
    We will create a multi-level map and set the elements with the key-values from the flatmap.
    The original map (non-flatten) must be the same as the multi-level map key-values.
     */
    org.platformlambda.core.util.MultiLevelMap mm = new org.platformlambda.core.util.MultiLevelMap();
    for (java.lang.String k : flatMap.keySet()) {
        mm.setElement(k, flatMap.get(k));
    }
    org.junit.Assert.assertEquals(map, mm.getMap());
    /* retrieval using composite keys from the multi-level map must match the original map's values */
    org.junit.Assert.assertEquals("data", mm.getElement(org.platformlambda.core.UtilityTests.HELLO_WORLD));
    org.junit.Assert.assertEquals(1, mm.getElement("hello.number[0]"));
    org.junit.Assert.assertEquals(2, mm.getElement("hello.number[1]"));
    org.junit.Assert.assertEquals("data", mm.getElement("hello.number[2].hello.world"));
    org.junit.Assert.assertEquals(1, mm.getElement("hello.number[2].hello.number[0]"));
    org.junit.Assert.assertEquals(2, mm.getElement("hello.number[2].hello.number[1]"));
    // really a lot of nested levels
    java.lang.String NESTED_PATH = "hello[5][4][3][2]";
    java.lang.String SIMPLE_VALUE = "world";
    org.platformlambda.core.util.MultiLevelMap m2 = new org.platformlambda.core.util.MultiLevelMap();
    m2.setElement(NESTED_PATH, SIMPLE_VALUE);
    java.util.Map<java.lang.String, java.lang.Object> m2flat = util.getFlatMap(m2.getMap());
    org.junit.Assert.assertEquals(SIMPLE_VALUE, m2flat.get(NESTED_PATH));
    org.junit.Assert.assertEquals(m2flat.get(NESTED_PATH), m2.getElement(NESTED_PATH));
    // alternate map and list
    java.lang.String MIX_PATH = "hello.world[0].headers[0]";
    org.platformlambda.core.util.MultiLevelMap m3 = new org.platformlambda.core.util.MultiLevelMap();
    m3.setElement(MIX_PATH, SIMPLE_VALUE);
    java.util.Map<java.lang.String, java.lang.Object> m3flat = util.getFlatMap(m3.getMap());
    org.junit.Assert.assertEquals(SIMPLE_VALUE, m3flat.get(MIX_PATH));
    org.junit.Assert.assertEquals(m3flat.get(MIX_PATH), m3.getElement(MIX_PATH));
}

