    final org.platformlambda.core.util.AppConfigReader config = org.platformlambda.core.util.AppConfigReader.getInstance();
    final boolean enableRest = "true".equals(config.getProperty("rest.automation", "false"));
    if (enableRest || (!org.platformlambda.core.system.AppStarter.wsLambdas.isEmpty())) {
        final org.platformlambda.core.util.Utility util = org.platformlambda.core.util.Utility.getInstance();
        final int port = util.str2int(config.getProperty("websocket.server.port", config.getProperty("rest.server.port", config.getProperty("server.port", "8085"))));
        if (port > 0) {
            final java.util.concurrent.BlockingQueue<java.lang.Boolean> serverStatus = new java.util.concurrent.ArrayBlockingQueue<>(1);
            final java.util.concurrent.ConcurrentMap<java.lang.String, org.platformlambda.automation.models.AsyncContextHolder> contexts;
            // create a dedicated vertx event loop instance for the HTTP server
            final io.vertx.core.Vertx vertx = io.vertx.core.Vertx.vertx();
            final io.vertx.core.http.HttpServer server = vertx.createHttpServer(new io.vertx.core.http.HttpServerOptions().setTcpKeepAlive(true));
            if (enableRest) {
                // start REST automation system
                org.platformlambda.core.util.ConfigReader restConfig = getRestConfig();
                org.platformlambda.automation.config.RoutingEntry restRouting = org.platformlambda.automation.config.RoutingEntry.getInstance();
                restRouting.load(restConfig);
