                    try {
                        platform.registerPrivate(org.platformlambda.core.system.AppStarter.ASYNC_HTTP_RESPONSE, new org.platformlambda.automation.services.ServiceResponseHandler(contexts), 200);
                    } catch (java.io.IOException e) {
