                    Housekeeper housekeeper = new Housekeeper(contexts);
                    platform.getVertx().setPeriodic(org.platformlambda.core.system.AppStarter.HOUSEKEEPING_INTERVAL, t -> housekeeper.removeExpiredConnections());
                    org.platformlambda.core.system.AppStarter.log.info("AsyncHttpContext housekeeper started");
                    org.platformlambda.core.system.AppStarter.log.info("Reactive HTTP server running on port-{}", service.actualPort());
                }
                if (!org.platformlambda.core.system.AppStarter.wsLambdas.isEmpty()) {
