public void stop() {
        if (consumer != null && consumer.isRegistered()) {
            // closing consumer
            consumer.unregister();
            // stopping worker
            for (WorkerQueues w: workers) {
                w.stop();
            }
            // completely close the associated elastic queue
            elasticQueue.destroy();
            consumer = null;
            stopped = true;
            log.info("{} stopped", route);
