            if (!s.contains("[")) {
                throw new java.lang.IllegalArgumentException("Invalid composite path - missing start bracket");
            }
            if (!s.endsWith("]")) {
                throw new java.lang.IllegalArgumentException("Invalid composite path - missing end bracket");
            }
            // check start-end pair
            int sep1 = s.indexOf('[');
            int sep2 = s.indexOf(']');
            if (sep2 < sep1) {
                throw new java.lang.IllegalArgumentException("Invalid composite path - missing start bracket");
            }
            boolean start = false;
            for (char c : s.substring(sep1).toCharArray()) {
                if (c == '[') {
                    if (start) {
                        throw new java.lang.IllegalArgumentException("Invalid composite path - missing end bracket");
                    } else {
                        start = true;
                    }
                } else if (c == ']') {
                    if (!start) {
                        throw new java.lang.IllegalArgumentException("Invalid composite path - duplicated end bracket");
                    } else {
                        start = false;
                    }
                } else if (start) {
                    if ((c < '0') || (c > '9')) {
                        throw new java.lang.IllegalArgumentException("Invalid composite path - indexes must be digits");
                    }
                } else {
                    throw new java.lang.IllegalArgumentException("Invalid composite path - invalid indexes");
                }
            }
        }
    }
}

