private void removeExpiredCache() {
        if (NOT_RUNNING.compareAndSet(true, false)) {
            Platform.getInstance().getEventExecutor().submit(() -> {
                try {
                    COLLECTION.keySet().forEach(k -> {
                        SimpleCache c = COLLECTION.get(k);
                        c.cleanUp();
                    });
                } finally {
                    NOT_RUNNING.set(true);
                }
            });
        }
    }

