                    EventEnvelope blk = new EventEnvelope()
                                            .setHeader(MultipartPayload.ID, event.getId())
                                            .setHeader(MultipartPayload.COUNT, count)
                                            .setHeader(MultipartPayload.TOTAL, total);
                    byte[] segment = new byte[maxPayload];
